//! ICC profiles for step 7 of `docs/MATHS.md`, generated by Little-CMS
//! from primaries and transfer curves. No binary ICC file lives in the
//! repository: each profile is built on demand from the constants below and
//! serialised with [`profile_bytes`] when it has to be embedded in a file.
//!
//! All profiles are ICC version 4 matrix/TRC display-class profiles with a
//! description tag naming negg and the space, a copyright tag, and (for the
//! D65 spaces) the Bradford `chad` tag that version 4 requires for a
//! non-D50 white.
//!
//! Little-CMS `Profile` values are `Send` but not `Sync`; build one per
//! thread rather than sharing a reference.

use lcms2::{CIExyY, CIExyYTRIPLE, Locale, MLU, Profile, Tag, TagSignature, ToneCurve};
use negg_types::settings::OutputSpace;

use crate::error::{CmsError, lcms_error};

/// Text of the profile copyright tag.
pub const COPYRIGHT: &str = "Generated by negg from published primaries. No rights reserved.";

/// The ICC version written into every generated profile.
const ICC_VERSION: f64 = 4.4;

/// D65 as CIE xyY (ITU-R BT.2020 and IEC 61966-2-1: x = 0.3127, y = 0.3290).
const D65_XY: CIExyY = CIExyY {
    x: 0.3127,
    y: 0.3290,
    Y: 1.0,
};

/// D50 as CIE xyY, the ICC profile connection space illuminant
/// (x = 0.3457, y = 0.3585).
const D50_XY: CIExyY = CIExyY {
    x: 0.3457,
    y: 0.3585,
    Y: 1.0,
};

const fn xy(x: f64, y: f64) -> CIExyY {
    CIExyY { x, y, Y: 1.0 }
}

/// Adobe RGB (1998) primaries, Adobe RGB (1998) Color Image Encoding
/// specification section 4.3.1.1.
const ADOBE_RGB: CIExyYTRIPLE = CIExyYTRIPLE {
    Red: xy(0.64, 0.33),
    Green: xy(0.21, 0.71),
    Blue: xy(0.15, 0.06),
};

/// Display P3 primaries: the DCI-P3 primaries of SMPTE EG 432-1 with the
/// D65 white of Apple's Display P3 encoding.
const DISPLAY_P3: CIExyYTRIPLE = CIExyYTRIPLE {
    Red: xy(0.680, 0.320),
    Green: xy(0.265, 0.690),
    Blue: xy(0.150, 0.060),
};

/// ROMM RGB (ProPhoto RGB) primaries, ISO 22028-2 table 1.
const PRO_PHOTO: CIExyYTRIPLE = CIExyYTRIPLE {
    Red: xy(0.7347, 0.2653),
    Green: xy(0.1596, 0.8404),
    Blue: xy(0.0366, 0.0001),
};

/// Rec.2020 primaries, ITU-R BT.2020 table 3. The same numbers as
/// [`crate::matrix::REC2020_RED`] and friends.
const REC2020: CIExyYTRIPLE = CIExyYTRIPLE {
    Red: xy(0.708, 0.292),
    Green: xy(0.170, 0.797),
    Blue: xy(0.131, 0.046),
};

/// The sRGB piecewise curve (IEC 61966-2-1) as Little-CMS parametric
/// type 4, `Y = (aX + b)^g` above `d` and `cX` below it, in the ICC
/// direction (encoded to linear).
fn srgb_curve() -> Result<ToneCurve, CmsError> {
    ToneCurve::new_parametric(4, &[2.4, 1.0 / 1.055, 0.055 / 1.055, 1.0 / 12.92, 0.04045])
        .map_err(|e| lcms_error("building the sRGB curve", e))
}

/// The inverse of the ITU-R BT.709 OETF (`V = 1.099 L^0.45 - 0.099` above
/// `L = 0.018`, `4.5 L` below; the same curve BT.2020 specifies for 10-bit
/// signals) as parametric type 4 in the ICC direction: `g = 1/0.45`,
/// `a = 1/1.099`, `b = 0.099/1.099`, `c = 1/4.5`, `d = 0.081`.
fn bt709_curve() -> Result<ToneCurve, CmsError> {
    ToneCurve::new_parametric(
        4,
        &[1.0 / 0.45, 1.0 / 1.099, 0.099 / 1.099, 1.0 / 4.5, 0.081],
    )
    .map_err(|e| lcms_error("building the BT.709 curve", e))
}

/// The display name of each output space, as used in the profile
/// description tag.
pub fn space_name(space: OutputSpace) -> &'static str {
    match space {
        OutputSpace::Srgb => "sRGB",
        OutputSpace::AdobeRgb => "Adobe RGB compatible",
        OutputSpace::DisplayP3 => "Display P3",
        OutputSpace::ProPhoto => "ProPhoto RGB",
        OutputSpace::Rec2020 => "Rec.2020",
    }
}

/// Writes a multi-localised Unicode text tag (`desc`, `cprt`).
fn set_text_tag(profile: &mut Profile, sig: TagSignature, text: &str) -> Result<(), CmsError> {
    let mut mlu = MLU::new(1);
    if !mlu.set_text(text, Locale::new("en_US")) {
        return Err(CmsError::Lcms(format!("setting the text of tag {sig:?}")));
    }
    profile.remove_tag(sig);
    if !profile.write_tag(sig, Tag::MLU(&mlu)) {
        return Err(CmsError::Lcms(format!("writing tag {sig:?}")));
    }
    Ok(())
}

/// Sets the version, description and copyright on a freshly built profile.
fn finish(mut profile: Profile, description: &str) -> Result<Profile, CmsError> {
    profile.set_version(ICC_VERSION);
    set_text_tag(
        &mut profile,
        TagSignature::ProfileDescriptionTag,
        description,
    )?;
    set_text_tag(&mut profile, TagSignature::CopyrightTag, COPYRIGHT)?;
    Ok(profile)
}

/// Builds a matrix/TRC RGB profile with one curve on all three channels.
fn rgb_profile(
    description: &str,
    white: &CIExyY,
    primaries: &CIExyYTRIPLE,
    curve: &ToneCurve,
) -> Result<Profile, CmsError> {
    let profile = Profile::new_rgb(white, primaries, &[curve, curve, curve])
        .map_err(|e| lcms_error(&format!("building the {description} profile"), e))?;
    finish(profile, description)
}

/// The output profile for `space` (step 7 of `docs/MATHS.md`, "Export"):
///
/// - `Srgb`: Little-CMS's built-in sRGB, which it generates from the
///   IEC 61966-2-1 primaries R(0.64, 0.33) G(0.30, 0.60) B(0.15, 0.06),
///   D65, and the sRGB piecewise curve.
/// - `AdobeRgb`: the Adobe RGB (1998) primaries, D65, gamma 2.2. Named
///   "Adobe RGB compatible" because it is built from the published numbers
///   rather than from Adobe's own file.
/// - `DisplayP3`: the SMPTE EG 432-1 P3 primaries, D65, the sRGB curve.
/// - `ProPhoto`: the ISO 22028-2 ROMM primaries, D50, gamma 1.8.
/// - `Rec2020`: the ITU-R BT.2020 primaries, D65, the BT.709 OETF.
///
/// # Errors
///
/// [`CmsError::Lcms`] if Little-CMS cannot build the profile or write its
/// tags, which does not happen for these constants short of allocation
/// failure.
pub fn output_profile(space: OutputSpace) -> Result<Profile, CmsError> {
    let description = format!("negg {}", space_name(space));
    match space {
        OutputSpace::Srgb => finish(Profile::new_srgb(), &description),
        OutputSpace::AdobeRgb => {
            rgb_profile(&description, &D65_XY, &ADOBE_RGB, &ToneCurve::new(2.2))
        }
        OutputSpace::DisplayP3 => rgb_profile(&description, &D65_XY, &DISPLAY_P3, &srgb_curve()?),
        OutputSpace::ProPhoto => {
            rgb_profile(&description, &D50_XY, &PRO_PHOTO, &ToneCurve::new(1.8))
        }
        OutputSpace::Rec2020 => rgb_profile(&description, &D65_XY, &REC2020, &bt709_curve()?),
    }
}

/// The serialised ICC version 4 profile for `space`, ready to embed in a
/// TIFF or JPEG. The description tag reads `negg <space name>`.
///
/// # Errors
///
/// As [`output_profile`], plus [`CmsError::Lcms`] if serialisation fails.
pub fn profile_bytes(space: OutputSpace) -> Result<Vec<u8>, CmsError> {
    output_profile(space)?
        .icc()
        .map_err(|e| lcms_error(&format!("serialising the {} profile", space_name(space)), e))
}

/// The working-space profile: linear Rec.2020 with a D65 white (decision 2,
/// `docs/ADR/0002-working-space-rec2020.md`), that is the BT.2020 primaries
/// with gamma 1.0. Every transform in [`crate::transform`] has this on one
/// side.
///
/// # Panics
///
/// Only if Little-CMS cannot allocate the profile; the inputs are constants
/// that are known to be valid.
pub fn working_profile() -> Profile {
    rgb_profile(
        "negg linear Rec.2020 (working space)",
        &D65_XY,
        &REC2020,
        &ToneCurve::new(1.0),
    )
    .expect("the working profile is built from valid constants")
}

#[cfg(test)]
mod tests {
    use super::*;
    use lcms2::{ColorSpaceSignature, InfoType};

    const ALL: [OutputSpace; 5] = [
        OutputSpace::Srgb,
        OutputSpace::AdobeRgb,
        OutputSpace::DisplayP3,
        OutputSpace::ProPhoto,
        OutputSpace::Rec2020,
    ];

    fn description(p: &Profile) -> String {
        p.info(InfoType::Description, Locale::none())
            .unwrap_or_default()
    }

    fn red_trc_gamma(p: &Profile) -> f64 {
        match p.read_tag(TagSignature::RedTRCTag) {
            Tag::ToneCurve(curve) => curve.estimated_gamma(0.01).expect("curve has a gamma"),
            other => panic!("red TRC is not a tone curve: {other:?}"),
        }
    }

    #[test]
    fn every_output_profile_round_trips_through_new_icc() {
        for space in ALL {
            let bytes = profile_bytes(space).unwrap();
            assert!(
                bytes.len() > 128,
                "{space:?}: {} bytes is not a profile",
                bytes.len()
            );
            let parsed = Profile::new_icc(&bytes).unwrap_or_else(|e| panic!("{space:?}: {e:?}"));
            assert_eq!(
                parsed.color_space(),
                ColorSpaceSignature::RgbData,
                "{space:?}"
            );
            assert!(parsed.is_matrix_shaper(), "{space:?} is not matrix/TRC");
            let version = parsed.version();
            assert!(
                (4.0..5.0).contains(&version),
                "{space:?}: version {version}"
            );
            let desc = description(&parsed);
            assert!(desc.starts_with("negg "), "{space:?}: description {desc:?}");
            assert!(
                desc.contains(space_name(space)),
                "{space:?}: description {desc:?}"
            );
            let cprt = parsed
                .info(InfoType::Copyright, Locale::none())
                .unwrap_or_default();
            assert_eq!(cprt, COPYRIGHT, "{space:?}");
        }
    }

    #[test]
    fn profile_bytes_are_deterministic() {
        for space in ALL {
            assert_eq!(
                profile_bytes(space).unwrap(),
                profile_bytes(space).unwrap(),
                "{space:?}"
            );
        }
    }

    #[test]
    fn descriptions_name_the_space() {
        assert_eq!(
            description(&output_profile(OutputSpace::Srgb).unwrap()),
            "negg sRGB"
        );
        assert_eq!(
            description(&output_profile(OutputSpace::AdobeRgb).unwrap()),
            "negg Adobe RGB compatible"
        );
        assert_eq!(
            description(&working_profile()),
            "negg linear Rec.2020 (working space)"
        );
    }

    #[test]
    fn gamma_profiles_carry_their_gamma() {
        let adobe = output_profile(OutputSpace::AdobeRgb).unwrap();
        assert!((red_trc_gamma(&adobe) - 2.2).abs() < 0.01);
        let pro_photo = output_profile(OutputSpace::ProPhoto).unwrap();
        assert!((red_trc_gamma(&pro_photo) - 1.8).abs() < 0.01);
        let working = working_profile();
        assert!((red_trc_gamma(&working) - 1.0).abs() < 0.01);
    }

    #[test]
    fn working_profile_is_v4_matrix_trc_with_chad() {
        let p = working_profile();
        assert!(p.is_matrix_shaper());
        assert!((4.0..5.0).contains(&p.version()));
        assert_eq!(p.color_space(), ColorSpaceSignature::RgbData);
        // A D65 profile in a D50 connection space needs the adaptation tag.
        assert!(p.has_tag(TagSignature::ChromaticAdaptationTag));
        assert!(p.has_tag(TagSignature::RedColorantTag));
        let bytes = p.icc().unwrap();
        assert!(Profile::new_icc(&bytes).is_ok());
    }

    #[test]
    fn d65_output_profiles_carry_the_adaptation_tag() {
        for space in [
            OutputSpace::DisplayP3,
            OutputSpace::Rec2020,
            OutputSpace::AdobeRgb,
        ] {
            let p = output_profile(space).unwrap();
            assert!(p.has_tag(TagSignature::ChromaticAdaptationTag), "{space:?}");
        }
    }

    #[test]
    fn space_names_are_distinct() {
        let mut names: Vec<_> = ALL.iter().map(|&s| space_name(s)).collect();
        names.sort_unstable();
        names.dedup();
        assert_eq!(names.len(), ALL.len());
    }
}
